effect.shader:
void main() {
    vec2 p = acScreenNorm - center; p.x *= acAspect;
    float r = length(p);
    vec2 n = (r > 1e-5) ? p / r : vec2(1.0, 0.0);
    float desl = sin(r * freq - phase + acTime * 2.0) * amp;
    vec2 off = n * desl; off.x /= max(acAspect, 1e-4);
    vec2 uv = acScreenNorm + off;

    int ns = clamp(int(samples), 2, 24);
    vec4 soma = vec4(0.0);
    for (int i = 0; i <= 24; i++) {
        if (i > ns) break;
        float t = (float(i)/float(ns) - 0.5) * blur;
        soma += texture(inputImg, uv + n * t);
    }
    fragColor = soma / float(ns + 1);
}
